                if let value = self.days {
                    try check(value.count >= 2, .days, in: container, "days at least 2 items")
                    try check(value.allSatisfy { [0,1,2,3,4,5,6].contains($0) }, .days, in: container, "each days one of 0, 1, 2, 3, 4, 5, 6")
                }
            }
        }

        public func encode(to encoder: Encoder) throws {
            var container = encoder.container(keyedBy: CodingKeys.self)
            try container.encode(self.interval, forKey: .interval)
            try container.encode(self.unit, forKey: .unit)
            try container.encodeIfPresent(self.days, forKey: .days)
        }
